lambda hand: any(
    (
        lambda num_aces, base_sum:
            (base_sum == 21 and num_aces == 0) or
            (
                num_aces > 0 and
                (21 - base_sum) >= num_aces and
                ((21 - base_sum) - num_aces) % 10 == 0 and
                ((21 - base_sum) - num_aces) // 10 <= num_aces
            )
    )(
        sum(1 for card in c if card['rank'] == 'A'),
        sum(
            10 if card['rank'] in ('10', 'J', 'Q', 'K') else int(card['rank'])
            for card in c if card['rank'] != 'A'
        )
    )
    for r in range(1, 7)
    for c in combinations(hand, r)
)

